import React from 'react';
import { View, Text, TouchableOpacity, ActivityIndicator } from 'react-native';

import { styles } from './styles';
import api from '../../services/api';
import { useContexState } from '../../hooks/context';

interface CardsProps {
    position: number,
    listItemProps: {
        data: { firstCard: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;
            }]
        };
    };
};

export function Cards({ listItemProps, position }: CardsProps) {
    const cardNumber = listItemProps.data.firstCard + position;
    const randomText = Math.random().toString(36).substr(2, 5);

    const { setIsMountedApi, isMountedApi } = useContexState();

    function cardPost() {
        api.post("register", {
            number: cardNumber,
            name: randomText,
            phone: '(00)000000000',
        }).then((response) => {
        });
    };

    function colorSelect() {
        if (listItemProps.list?.[String(cardNumber)]) {
            return {
                backgroundColor: listItemProps.list?.
                [cardNumber][0].price !== 0 ? '#26A744' : '#17A2B7'
            }
        } else return {
            backgroundColor: '#fff',
            color: '#121212'
        }
    };

    return (isMountedApi ?
        (cardNumber <= 9999 && cardNumber >= 0 ?
            <TouchableOpacity onPress={cardPost}>
                <View>
                    <Text style={[styles.listText, colorSelect()
                    ]}>
                        {(`0000${cardNumber}`).slice(-4)}
                    </Text>
                </View>
            </TouchableOpacity> : null) : <View style={styles.load}>
            <ActivityIndicator size={25} color='#fff' />

        </View>
    );
};
